commit b06ac66dbf0ffb27694b65c067ef74b54f07e6e8
Fix a Close leak

diff -- pkg/codegen/schema/loader_mmap.go
@@ -40,7 +40,10 @@ func (l *pluginLoader) loadCachedSchemaBytes(path string, pluginInstallTime time
 	success := false
 	schemaFile, err := os.OpenFile(path, os.O_RDONLY, 0o644)
 	defer func() {
-		if !success {
+		// Close on failure, or on a plain read where the data has already been
+		// copied. For mmap, the file must remain open while the mapping is active
+		// (required on Windows), so we leave it open in that case.
+		if !success || l.cacheOptions.disableMmap {
 			schemaFile.Close()
 		}
 	}()

commit 00414c1eb5b9126a0fa8f9b7dd631d3f30e098df
Don't fail on cache failures

diff -- pkg/codegen/schema/loader.go
@@ -36,6 +36,7 @@ import (
 	"github.com/pulumi/pulumi/sdk/v3/go/common/resource/plugin"
 	"github.com/pulumi/pulumi/sdk/v3/go/common/tokens"
 	"github.com/pulumi/pulumi/sdk/v3/go/common/util/contract"
+	"github.com/pulumi/pulumi/sdk/v3/go/common/util/logging"
 	"github.com/pulumi/pulumi/sdk/v3/go/common/workspace"
 )

@@ -490,9 +491,12 @@ func (l *pluginLoader) loadSchemaBytes(

 	if schemaPath != "" {
 		if mkdirErr := os.MkdirAll(filepath.Dir(schemaPath), 0o700); mkdirErr == nil {
-			err = atomic.WriteFile(schemaPath, bytes.NewReader(schemaBytes))
-			if err != nil {
-				return nil, nil, fmt.Errorf("Error writing schema from plugin to cache: %w", err)
+			if writeErr := atomic.WriteFile(schemaPath, bytes.NewReader(schemaBytes)); writeErr != nil {
+				// Cache writes are best-effort. On Windows, os.Rename (used internally
+				// by atomic.WriteFile) fails with "Access Denied" when a concurrent
+				// loader has already written and memory-mapped the same file. The
+				// schema bytes are still valid — we just lost the race to cache them.
+				logging.V(3).Infof("failed to cache schema at %s: %v", schemaPath, writeErr)
 			}
 		}
 	}
